FORM.direct_two_parameters:
/* PointInRect: read the point and rectangle as far structures. With a ribbon, the right and bottom bounds are exclusive; otherwise both are inclusive. The named far ribbonBarHeight is the policy switch. */
struct Point { int x; int y; };
struct PointRect { int left; int top; int right; int bottom; };
extern int far ribbonBarHeight;
int far PointInRect(struct Point far *point, struct PointRect far *rect)
{
    if (ribbonBarHeight)
        return point->x < rect->right && point->x >= rect->left &&
               point->y >= rect->top && point->y < rect->bottom;
    return point->x <= rect->right && point->x >= rect->left &&
           point->y >= rect->top && point->y <= rect->bottom;
}

FORM.point_local_alias:
/* PointInRect: read the point and rectangle as far structures. With a ribbon, the right and bottom bounds are exclusive; otherwise both are inclusive. The named far ribbonBarHeight is the policy switch. */
struct Point { int x; int y; };
struct PointRect { int left; int top; int right; int bottom; };
extern int far ribbonBarHeight;
int far PointInRect(struct Point far *point, struct PointRect far *rect)
{
    struct Point far *p;
    p = point;
    if (ribbonBarHeight)
        return p->x < rect->right && p->x >= rect->left &&
               p->y >= rect->top && p->y < rect->bottom;
    return p->x <= rect->right && p->x >= rect->left &&
           p->y >= rect->top && p->y <= rect->bottom;
}
